38: static inline bool GetBoolEnvironmentVariable( const char * name ) {
39:     if ( const char* s = std::getenv(name) ) {
40:         // The result is defined as true only if the environment variable contains
41:         // no characters except one '1' character and an arbitrary number of spaces
42:         // (including the absence of spaces).
43:         size_t index = std::strspn(s, " ");
44:         if (s[index] != '1') return false;
45:         index++;
46:         // Memory access after incrementing is safe, since the getenv() returns a
47:         // null-terminated string, and even if the character getting by index is '1',
48:         // and this character is the end of string, after incrementing we will get
